async function build(){let b=fs.readFileSync(path.join(root,'build.mjs'),'utf8').replace(/\r\n/g,'\n');result.inputHashes=Object.fromEntries(['build.mjs','public/index.html','public/js/app.js','tools/test-deep-models.cjs'].map(f=>[f,hash(fs.readFileSync(path.join(root,f)))]));b=once(b,'const ROOT = path.dirname(fileURLToPath(import.meta.url));',`const ROOT = ${JSON.stringify(root)};`);b=once(b,"const app = read('js/app.js');",`const app = read('js/app.js').replace('window.__SE = {', 'window.__SE = { __p: {timeAtLg:cineTimeAtLg,JOURNEY,cosmicBuild,cosmicUpdate,getFrame:()=>frameId},');`);b=once(b,`for (const name of ['space.html', 'index.html']) {\n  fs.writeFileSync(path.join(ROOT, name), htmlOffline);\n}\nfs.writeFileSync(path.join(ROOT, 'space-http.html'), htmlHttp);`,`fs.writeFileSync(${JSON.stringify(path.join(output,'preview.html'))}, htmlOffline, {flag:'wx'});`);await import('data:text/javascript;base64,'+Buffer.from(b).toString('base64'));result.previewSha256=hash(fs.readFileSync(path.join(output,'preview.html')));}
